import { ActionButton } from 'office-ui-fabric-react/lib/Button';
import React, { useState, useEffect } from 'react';
import { useTranslation } from 'react-i18next';

import IconButton from '../../../../../components/IconButton/IconButton';
import { TextField } from 'office-ui-fabric-react';
import ActionBar from '../../../../../components/ActionBar';
import { newButtonOfficeFabricStyle, textBoxListStyle, textBoxInListStyle, textBoxInListDeleteButtonStyle } from '../../AppSettings.styles';

interface Props {
  clientExclusionPaths: string;
  save: (clientExclusionPaths: string) => void;
  cancel: () => void;
}
const EditClientExclusionPaths: React.FC<Props> = props => {
  const { clientExclusionPaths, save, cancel } = props;
  const [focusLast, setFocusLast] = useState(false);
  const [values, setValues] = useState(clientExclusionPaths ? clientExclusionPaths.split(';') : []);
  const { t } = useTranslation();
  let lastFieldRef: any;
  // This is a hook that is run after render if finished
  useEffect(() => {
    if (focusLast) {
      lastFieldRef.focus();
      setFocusLast(false);
    }

    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [focusLast]);

  const removeItem = (index: number) => {
    setValues(values.filter((v, i) => i !== index));
  };

  const onChange = (index: number) => (e: any, newValue: string) => {
    const valuesCopy = [...values];
    valuesCopy[index] = newValue;
    setValues(valuesCopy);
  };
  const createNewItem = () => {
    setFocusLast(true);
    setValues([...values, '']);
  };

  const actionBarPrimaryButtonProps = {
    id: 'save',
    title: t('ok'),
    onClick: () => {
      save(values.join(';'));
    },
    disable: false,
  };

  const actionBarSecondaryButtonProps = {
    id: 'cancel',
    title: t('cancel'),
    onClick: cancel,
    disable: false,
  };
  return (
    <>
      <ActionButton
        id="app-settings-new-client-exclusion-path"
        onClick={createNewItem}
        styles={newButtonOfficeFabricStyle}
        iconProps={{ iconName: 'Add' }}>
        {t('newPath')}
      </ActionButton>
      <ol>
        {values.map((value, index) => (
          <li key={index} className={textBoxListStyle}>
            <div className={textBoxInListStyle}>
              <TextField
                componentRef={field => {
                  lastFieldRef = field;
                }}
                value={value}
                onChange={onChange(index)}
                label=""
                id={`app-settings-exclusion-path-text-${index}`}
                ariaLabel={t('defaultDocuments')}
                underlined
                {...props}
              />
            </div>
            <IconButton
              id={`app-settings-exclusion-path-delete-${index}`}
              className={textBoxInListDeleteButtonStyle}
              iconProps={{ iconName: 'Delete' }}
              title={t('delete')}
              onClick={() => removeItem(index)}
            />
          </li>
        ))}

import {Operator} from '../Operator';
import {Subscriber} from '../Subscriber';
import {Observable} from '../Observable';
import {Subject} from '../Subject';

export function windowCount<T>(windowSize: number,
                               startWindowEvery: number = 0): Observable<Observable<T>> {
  return this.lift(new WindowCountOperator<T>(windowSize, startWindowEvery));
}

export interface WindowCountSignature<T> {
  (windowSize: number, startWindowEvery?: number): Observable<Observable<T>>;
}

class WindowCountOperator<T> implements Operator<T, Observable<T>> {

  constructor(private windowSize: number,
              private startWindowEvery: number) {
  }

  call(subscriber: Subscriber<Observable<T>>): Subscriber<T> {
    return new WindowCountSubscriber(subscriber, this.windowSize, this.startWindowEvery);
  }
}

class WindowCountSubscriber<T> extends Subscriber<T> {
  private windows: Subject<T>[] = [ new Subject<T>() ];
  private count: number = 0;

  constructor(protected destination: Subscriber<Observable<T>>,
              private windowSize: number,
              private startWindowEvery: number) {
    super(destination);
    const firstWindow = this.windows[0];
    destination.add(firstWindow);
    destination.next(firstWindow);
  }

  protected _next(value: T) {
    const startWindowEvery = (this.startWindowEvery > 0) ? this.startWindowEvery : this.windowSize;
    const destination = this.destination;
    const windowSize = this.windowSize;
    const windows = this.windows;
    const len = windows.length;

    for (let i = 0; i < len; i++) {
      windows[i].next(value);
    }
    const c = this.count - windowSize + 1;
    if (c >= 0 && c % startWindowEvery === 0) {
      windows.shift().complete();
    }
    if (++this.count % startWindowEvery === 0) {
      const window = new Subject<T>();
      windows.push(window);
      destination.add(window);
      destination.next(window);
    }
  }

  protected _error(err: any) {
    const windows = this.windows;
    while (windows.length > 0) {
      windows.shift().error(err);
    }
    this.destination.error(err);
  }

  protected _complete() {
    const windows = this.windows;
    while (windows.length > 0) {
      windows.shift().complete();
    }
    this.destination.complete();
  }
}

# How do I reverse “Cartesian->Isometric” function?

I'm working on an isometric tile rendering engine and I need to reverse a function I used to translate the Cartesian coordinates into isometric coordinates. I've already written a function for this, but I've been getting a strange logical error and I think it must be somewhere in my code for translating from isometric coordinates back into Cartesian. Anyways, here's the code for translating Cartesian->Isometric

    private Vector2 cartToIso(Vector2 init){
Vector2 iso = new Vector2();
iso.x = (((init.x - init.y) * TILE_WIDTH_HALF))+X_OFFSET;
iso.y = MAP_HEIGHT-TILE_HEIGHT-((init.x + init.y) * TILE_HEIGHT_HALF);
return iso;
}


Any suggestions would be appreciated. Also if anyone was wondering, what I'm trying to do right now is create an algorithm for tile picking in my engine. The API(LibGDX) is a little strange in the sense that it uses a bottom-up Y coordinate system but with any of the input(ie, clicks) it uses a top-down Y coordinate system. I can post the code I have for tile picking later if anyone thinks they can help me more, but I'll save it for now since it's pretty long.

Edit: This is the method I use to reverse it, and it seems to be giving me the incorrect results. Does this look correct?

    private Vector2 isoToCart(int x, int y){
Vector2 cart = new Vector2();
x = x-X_OFFSET;
y = y-MAP_HEIGHT;
cart.x = (x / TILE_WIDTH_HALF + (y / TILE_HEIGHT_HALF)) /2;
cart.y = (y / TILE_HEIGHT_HALF -(x / TILE_WIDTH_HALF)) /2;
return cart;
}

• Can you describe what the "strange logical error" you're encountering is? What are the symptoms? This will help people searching for similar problems in future find this post and its answers. – DMGregory Mar 24 '15 at 15:47
• No problem at all. When you try to select tiles approaching x=0, the x and y coordinates that it selects are off by 1. X is usually incremented and the Y is usually decremented. – Jesse Mar 24 '15 at 22:40
• Anyone have any suggestions? – Jesse Mar 25 '15 at 23:13

If you ignore the constants you have in your calculations (such as tile width, for example) the calculations for isometric to cartesian and back are usually;

float isometricX = cartesianX - cartesianY;
float isometricY = (cartesianX + cartesianY) * 0.5f;


And the reverse is

float cartesianX = (2.0f * isometricY + isometricX) * 0.5f;
float cartesianY = (2.0f * isometricY - isometricX) * 0.5f;


That's assuming square tiles of unit length.

I'm not sure how your MAP_HEIGHT plays into this, but you should be able to scale that by your tile size to get the values need for your game.

Edit; To use this to pick a tile the following method could be used (note that here tileSize is the height of the tile, so in your case 32px);

private Vector2 screenToMap(float screenX, float screenY) {
float mapx = (screenX / tileSize + screenY / (tileSize * 0.5f)) * 0.5f;
float mapy = (screenY / (tileSize * 0.5f) - (screenX / tileSize)) * 0.5f;
return new Vector2(mapx - 0.5f, mapy + 0.5f);

